package com.example.jwtlogin.security.services; import com.example.jwtlogin.model.User; import com.example.jwtlogin.repository.UserRepository; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import java.util.List;
@Service public class UserDetailsServiceImpl implements UserDetailsService { @Autowired UserRepository repo; @Override public UserDetails loadUserByUsername(String u) throws UsernameNotFoundException { User user=repo.findByUsername(u).orElseThrow(()->new UsernameNotFoundException("User not found")); return new org.springframework.security.core.userdetails.User(user.getUsername(), user.getPassword(), List.of(new SimpleGrantedAuthority(user.getRole()))); } }
